pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 maxM, uint256 minM, uint256 rateVal, address caller) public {
        // 1. keep parameters in a wide admissible domain
        maxM = bound(maxM, 1e27, type(uint256).max / 2);
        minM = bound(minM, 0, maxM);
        rateVal = bound(rateVal, 1, 1e27);
        vm.assume(caller != address(0));

        // 2. adversarial counterparty: a functional access-control contract whose
        //    granting decision is itself fuzzed through its public surface
        MockAC ac = new MockAC();
        bool grantFlag = uint256(keccak256(abi.encode(caller, maxM))) % 2 == 0;
        ac.setGrant(grantFlag);

        c.initialize(address(ac));

        // 3. drive an access-checked entry point from an arbitrary caller
        vm.prank(caller);
        bool ok;
        try c.setLimits(maxM, minM, rateVal) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever the configured access control grants access,
        // initialize must have wired it up so any access-checked call succeeds.
        assertTrue(grantFlag ? ok : true);
    }
}

contract MockAC {
    bool private grant;

    function setGrant(bool g) external { grant = g; }

    function checkAccess(bytes4, address, address) external view returns (bool) {
        return grant;
    }
}

