pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 kink, uint256 slope0, uint256 slope1) public {
        // Keep slope parameters in the admissible domain: 0 < kink < 1e27
        kink = bound(kink, 1, 1e27 - 1);

        // Deploy a real access-control counterparty that grants every access check.
        FakeAC ac = new FakeAC();

        // Drive c through initialize with the genuine access control.
        c.initialize(address(ac));

        IVaultAdapter.SlopeData memory slopes =
            IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1});

        // The authorized setter must go through (access stored in initialize must be honored).
        bool ok;
        try c.setSlopes(address(0xA11CE), slopes) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after initializing with a working access control that grants access,
        // setSlopes succeeds for any admissible slope data. The mutant initialized with
        // address(1), so every access check fails and this call reverts.
        assertTrue(ok);
    }
}

// Minimal adversarial/enabling counterparty: an access-control contract that grants all access.
contract FakeAC {
    function checkAccess(bytes4, address, address) external pure returns (bool) {
        return true;
    }
}
